#include <iostream>
#include <string>
#include <vector>

enum Anchor : unsigned { LEFT = 1, TOP = 2, RIGHT = 4, BOTTOM = 8 };

struct Control
{
    std::string name{};
    int x{}, y{}, w{}, h{};
    unsigned anchors{LEFT | TOP};
};

Control layout(const Control& c, int oldW, int oldH, int newW, int newH)
{
    return c;
}

int main()
{
    Control ok{"OK", 310, 260, 80, 30, RIGHT | BOTTOM};
    Control r{layout(ok, 400, 300, 600, 400)};
    std::cout << r.x << ' ' << r.y << '\n';
}
